<script setup lang="ts">import { reactive,ref } from 'vue'; import { onLoad,onShow } from '@dcloudio/uni-app'; import type { ResumeEntry } from '@/utils/resume'; const type=ref<'education'|'work'|'projects'>('work'); const index=ref(-1); const entry=reactive<ResumeEntry>({}); const title=ref('工作经历'); const detailPlaceholder=`采用STAR法则描述你的工作内容、项目成果或负责事项，例如：
1、针对 XX 问题，负责 XX 目标，通过 XX 方法（做了 XX、XX、XX），最终实现 XX 结果，XX 指标提升/降低 XX%。
2、针对 XX 区域客户基础薄弱问题，制定分级跟进策略并联合 XX 部门演示，将月成交从 XX 单提升至 XX 单，超额完成 XX%。
3、针对 XX 产品初期日活仅 XX 的问题，负责 XX 个月增长目标，策划 XX 裂变活动并联合 XX 个社群推广，最终日活提升至 XX，获客成本降低 XX%。`; onLoad(q=>{type.value=(q?.type||'work') as typeof type.value;index.value=Number(q?.index??-1);title.value=type.value==='education'?'教育经历':type.value==='projects'?'项目经历':'工作经历'}); onShow(()=>{const d=uni.getStorageSync('resume-draft')||{};const list=d[type.value]||[];Object.assign(entry,list[index.value]||{})}); function save(){const d=uni.getStorageSync('resume-draft')||{};const list=d[type.value]||[];if(index.value<0){list.push({...entry});}else list.splice(index.value,1,{...entry});d[type.value]=list;uni.setStorageSync('resume-draft',d);uni.navigateBack()} function remove(){uni.showModal({title:'确认删除',content:`确定删除这条${title.value}吗？`,success:({confirm})=>{if(!confirm)return;const d=uni.getStorageSync('resume-draft')||{};(d[type.value]||[]).splice(index.value,1);uni.setStorageSync('resume-draft',d);uni.navigateBack()}})}</script>
<template><view class="page"><view class="card"><template v-if="type==='education'"><text class="label">学校名称</text><input v-model="entry.school" class="input" placeholder="请输入学校"/><text class="label">专业 / 学位</text><input v-model="entry.major" class="input" placeholder="请输入专业或学位"/></template><template v-else-if="type==='projects'"><text class="label">项目名称</text><input v-model="entry.name" class="input" placeholder="请输入项目名称"/><text class="label">担任角色</text><input v-model="entry.role" class="input" placeholder="请输入角色"/></template><template v-else><text class="label">公司名称</text><input v-model="entry.company" class="input" placeholder="请输入公司名称"/><text class="label">职位</text><input v-model="entry.role" class="input" placeholder="请输入职位"/></template><text class="label">时间</text><input v-model="entry.time" class="input" placeholder="如：2021.06 - 至今"/><template v-if="type!=='education'"><text class="label">经历描述</text><textarea v-model="entry.detail" class="textarea" auto-height :maxlength="-1" :placeholder="detailPlaceholder"/></template></view><button class="save" @click="save">完成</button><button v-if="index>=0" class="delete-button" @click="remove">删除此条经历</button></view></template>
<style scoped lang="scss">.page{min-height:100vh;padding:18px 16px;background:#f5f6fa}.card{padding:18px 16px;background:#fff;border-radius:12px}.label{display:block;margin:2px 0 8px;color:#344054;font-size:13px}.input,.textarea{width:100%;box-sizing:border-box;margin-bottom:15px;padding:0 12px;border:1px solid #e2e8f0;border-radius:8px;background:#f8fafc;font-size:14px}.input{height:44px}.textarea{min-height:150px;padding-top:12px;padding-bottom:12px;line-height:22px;height:auto}.save,.delete-button{height:48px;margin-top:22px;border-radius:24px;line-height:48px}.save{background:#2563eb;color:#fff}.delete-button{border:1px solid #fecaca;background:#fff;color:#ef4444}</style>
